import {createArchiveClient} from './archive-client.mjs';
import {downloadProof} from './proof-export.mjs';
'use strict';
const apiBase=String(window.ARCHIVE_CONFIG?.apiBaseUrl||'').replace(/\/$/,'');
function apiUrl(path){if(!apiBase)throw Error('平台迁移尚未完成，请稍后再试。');return apiBase+path}
function assetUrl(path){return new URL(path,document.baseURI).href}
const archive=createArchiveClient(apiBase,fetch,window.ARCHIVE_CONFIG?.dataBaseUrl||apiBase);
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let stats={},tokenTime=0,current=null,activeReview=null,studentOffset=0,docOffset=0,fileOffset=0,view='students';
const labels={students:['学生获奖查询','从学生基本信息出发，查找历年获奖记录与存档佐证。'],documents:['佐证材料检索','定位原件中的表格行、文档段落与 PDF 页面。'],coverage:['处理概览','查看材料覆盖范围、读取结果与需要补查的文件。'],history:['材料出具记录','追溯每一份证明草稿所采用的记录和核验依据。']};
async function api(url,body){if(!body){if(!apiBase)throw Error('平台迁移尚未完成，请稍后再试。');const local=await archive.query(url);if(local!==null){if(url==='/api/stats')tokenTime=Date.now();return local}}else if(Date.now()-tokenTime>1800000){const fresh=await fetch(apiUrl('/api/workflow/stats'));if(!fresh.ok)throw Error('暂时无法连接档案库，请稍后再试');stats.token=(await fresh.json()).token;tokenTime=Date.now()}const r=await fetch(apiUrl(url),body?{method:'POST',headers:{'Content-Type':'application/json','X-Archive-Token':stats.token},body:JSON.stringify(body)}:{});if(!r.ok){let e;try{e=await r.json()}catch{e={error:'请求失败，请刷新后重试'}}throw Error(e.error||'请求失败')}return r.json()}
function toast(s){$('#toast').textContent=s;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,4500)}
function fail(e){toast(e.message||String(e))}
function tag(t){return `<span class="tag ${t==='已核实'?'green':/待|申请|公示|未获|排除|失败/.test(t)?'amber':''}">${esc(t)}</span>`}
function pageButtons(target,offset,size,total,handler){$(target).innerHTML=`${offset>0?`<button data-page="${handler}" data-offset="${Math.max(0,offset-size)}">上一页</button>`:''}<span>第 ${Math.floor(offset/size)+1} 页${total!=null?' · '+total.toLocaleString()+' 条':''}</span>${total==null||offset+size<total?`<button data-page="${handler}" data-offset="${offset+size}">下一页</button>`:''}`}
async function loadStats(){stats=await api('/api/stats');const pending=(stats.states['待OCR']||0)+(stats.states['待处理']||0)+(stats.states['待旧版Word转换']||0);const messages=[];if(stats.meta.sync_phase)messages.push(stats.meta.sync_phase);if(pending)messages.push('材料整理仍在进行：'+pending.toLocaleString()+' 份材料尚待识别或补读。无命中时请结合待处理材料补查。 '+(stats.meta.ocr_phase||''));$('#processing-status').hidden=!messages.length;$('#processing-status').textContent=messages.join(' · ');const fmt=n=>Number(n).toLocaleString();$('#stats').innerHTML=[['学生档案',stats.students,'按学号区分身份','◈'],['获奖及参评线索',stats.observations,'包含申请、推荐和待核材料','▤'],['原始材料',stats.files,'含压缩包内独立材料','▧'],['已核验记录',stats.reviews,'人工核验操作次数','✓']].map(([t,n,f,i])=>`<div class="stat"><div class="stat-top">${t}<span class="stat-symbol">${i}</span></div><div class="stat-number">${fmt(n)}</div><div class="stat-foot">${f}</div></div>`).join('');for(const [sel,key,first] of [['#year','years','全部年度 / 学年'],['#award','awards','全部奖项']]){const val=$(sel).value;$(sel).innerHTML=`<option value="">${first}</option>`+stats[key].map(x=>`<option>${esc(x)}</option>`).join('');$(sel).value=val}$('#updated').textContent=stats.meta.updated?'最近整理：'+stats.meta.updated:stats.meta.phase||'正在整理材料';}
async function findStudents(offset=0){studentOffset=offset;$('#student-list').innerHTML='<div class="loading">正在查询档案…</div>';const p=new URLSearchParams({q:$('#query').value.trim(),college:$('#college').value.trim(),year:$('#year').value,award:$('#award').value,offset});const r=await api('/api/students?'+p);$('#result-count').textContent=r.total.toLocaleString()+' 人';$('#student-list').innerHTML=r.items.length?`<table><thead><tr><th>学生</th><th>学号</th><th>学院 / 书院</th><th>奖项线索</th><th></th></tr></thead><tbody>${r.items.map(s=>`<tr><td><div class="student-name"><span class="avatar">${esc((s.name||'学').slice(-2))}</span>${esc(s.name||'姓名待补全')} ${s.conflict?tag('姓名有差异'):''}</div></td><td class="mono">${esc(s.sid)}</td><td>${esc(s.college||'—')}</td><td><span class="tag">${s.awards} 项 / 年度</span></td><td><button class="text-button" data-student="${esc(s.sid)}">查看档案 →</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">未找到匹配学生。可更换姓名或学号，或在“佐证材料检索”中补查原件。</div>';pageButtons('#student-pagination',offset,50,r.total,'students')}
async function openStudent(sid){$('#student-dialog').showModal();$('#student-detail').innerHTML='<div class="loading">正在汇集获奖线索和佐证…</div>';try{current=await api('/api/student/'+encodeURIComponent(sid));renderStudent()}catch(e){$('#student-detail').innerHTML=`<div class="empty">档案暂未载入，请重试。<p><button class="text-button" data-student="${esc(sid)}">重新加载档案</button></p></div>`;throw e}}
function renderStudent(){const s=current.student;$('#student-title').textContent=(s.name||'姓名待补全')+' · 学生档案';$('#student-subtitle').textContent=s.sid+'  /  '+(s.college||'学院待补全');const groups=new Map();for(const o of current.observations){if(['参考材料','未获奖/放弃'].includes(o.stage))continue;const k=o.year+'|'+o.award;if(!groups.has(k))groups.set(k,[]);groups.get(k).push(o)}const latest=new Map();for(const r of current.reviews)if(!latest.has(r.observation))latest.set(r.observation,r);
let content=(s.conflict?'<div class="notice warning">同一学号在材料中出现不同姓名，请先核对身份。系统保留全部原始记录。</div>':'')+'<div class="notice">下列是材料中检出的获奖及参评线索。公示、推荐、目录推断年度均保留原始状态；核验后才能用于证明。</div>';
content+=groups.size?[...groups].map(([k,obs])=>`<section class="award-group"><div class="award-heading"><div><strong>${esc(obs[0].award)}</strong><small>${esc(obs[0].year)}</small></div><span class="count">${obs.length} 处来源</span></div>${obs.slice(0,2).map(o=>obsRow(o,latest.get(o.id))).join('')}${obs.length>2?`<details><summary style="padding:12px 17px">查看其余 ${obs.length-2} 处来源</summary>${obs.slice(2).map(o=>obsRow(o,latest.get(o.id))).join('')}</details>`:''}</section>`).join(''):'<div class="empty">暂无结构化奖项线索，可在下方原始材料命中处核对。</div>';
const approved=[...latest.values()].filter(r=>r.decision==='已核实');if(approved.length)content+=`<h2 class="section-title">已核实记录 ${approved.length} 条</h2>${approved.map(r=>`<div class="evidence-row">${tag('已核实')} ${esc(r.year)} · ${esc(r.award)} ${esc(r.level)}<p>${esc(r.reviewer)} · ${esc(r.note)}</p></div>`).join('')}`;
if(current.candidates.length)content+=`<details><summary>同名候选材料 ${current.candidates.length} 处（未按姓名自动合并）</summary>${current.candidates.map(o=>obsRow(o,latest.get(o.id))).join('')}</details>`;
const refs=current.observations.filter(o=>['参考材料','未获奖/放弃'].includes(o.stage));if(refs.length)content+=`<details><summary>参考或未获奖材料 ${refs.length} 处</summary>${refs.map(o=>obsRow(o,latest.get(o.id))).join('')}</details>`;
content+=`<details><summary>学号在原始材料中的命中位置 ${current.evidence.length}${current.evidence.length===150?'（展示前150条）':''} 处</summary>${current.evidence.map(e=>`<div class="evidence-row"><button class="text-button" data-source="${e.source}" data-locator="${esc(e.locator)}">${esc(e.path)}</button><p>${esc(e.locator)} · ${esc(e.method)}</p><pre class="excerpt">${esc(e.excerpt)}</pre></div>`).join('')}</details>`;$('#student-detail').innerHTML=content;}
function obsRow(o,r){return `<div class="evidence-row"><div class="evidence-actions"><div class="evidence-meta">${tag(r?r.decision:o.stage)}<span>${esc(o.level||'等级未注明')}</span><span>${esc(o.year_basis)}</span>${o.amount?`<span>金额：${esc(o.amount)}</span>`:''}</div><button class="text-button" data-review="${o.id}">核验记录</button></div><p><button class="text-button" data-source="${o.source}" data-locator="${esc(o.locator)}">${esc(o.path)}</button></p><p>${esc(o.locator)} · ${esc(o.method)}${o.name?' · '+esc(o.name):''}${o.sid?' · '+esc(o.sid):''}</p><details><summary>查看定位摘录</summary><pre class="excerpt">${esc(o.excerpt)}</pre></details></div>`}
async function openSource(id,locator=''){const d=$('#source-dialog');if(!d.open)d.showModal();$('#source-content').innerHTML='<div class="loading">正在读取佐证…</div>';const r=await api('/api/source/'+id+'?'+new URLSearchParams({locator}));$('#source-name').textContent=r.source.path;let t=`<div class="evidence-actions"><div>${tag(r.source.state)} <span class="mono">${esc(r.source.ext)}</span></div><a class="button secondary" target="_blank" href="${apiUrl('/api/source/'+id+'/file?download=1')}" rel="noreferrer">下载原件</a></div><p class="mono" style="font-size:10px;overflow-wrap:anywhere;margin-top:12px">SHA-256：${esc(r.source.sha||'尚未计算')}</p>`;if(r.source.message)t+=`<div class="notice" style="margin-top:15px">${esc(r.source.message)}</div>`;if(r.source.ext==='.pdf'){const m=locator.match(/第(\d+)页/);const page=m?Number(m[1]):1,total=r.source.pages||1;t+=`<div class="pdf-controls" data-pdf-id="${id}" data-pdf-total="${total}"><button class="button secondary" data-pdf-step="-1">上一页</button><label>页码 <input id="pdf-page" type="number" min="1" max="${total}" value="${page}" aria-label="PDF页码"></label><span> / ${total} 页</span><button class="button secondary" data-pdf-step="1">下一页</button><button class="text-button" id="register-pdf-page" data-manual="${id}" data-locator="第${page}页">根据此页登记并核验</button></div><p id="pdf-status" role="status">正在载入原件…</p><canvas class="pdf-page-image" id="pdf-image" aria-label="PDF原件第${page}页"></canvas>`}else if(['.jpg','.png','.jpeg'].includes(r.source.ext))t+=`<img alt="佐证扫描原件" src="${apiUrl('/api/source/'+id+'/file')}">`;
let rr=r.chunks;if(locator)rr=[...r.chunks.filter(c=>c.locator===locator),...r.chunks.filter(c=>c.locator!==locator)];t+='<h2 class="section-title">内容定位'+(r.chunks.length>=5000?'（前5000处）':'')+'</h2>'+rr.slice(0,120).map(c=>`<details ${c.locator===locator?'open':''}><summary>${esc(c.locator)} · ${esc(c.method)}</summary><button class="text-button" data-manual="${id}" data-locator="${esc(c.locator)}" data-chunk="${c.id}">根据此处原件登记并核验</button><pre class="excerpt">${esc(c.text)}</pre></details>`).join('');$('#source-content').innerHTML=t;if(r.source.ext==='.pdf')showPdfPage(id,Number($('#pdf-page').value)).catch(fail);}
function reviewRecord(id){activeReview=[...current.observations,...current.candidates].find(o=>o.id===Number(id));if(!activeReview)return;const form=$('#review-form');form.reset();const prior=current.reviews.find(r=>r.observation===activeReview.id);for(const k of ['sid','name','college','award','year','level'])form.elements[k].value=(prior||activeReview)[k]||current.student[k]||'';if(prior){form.elements.note.value=prior.note;form.elements.reviewer.value=prior.reviewer;form.elements.decision.value=prior.decision}$('#review-dialog').showModal()}
async function saveReview(e){e.preventDefault();const b=Object.fromEntries(new FormData(e.target));if(activeReview.id==null){const created=await api('/api/manual',{...b,source:activeReview.source,locator:activeReview.locator,chunk_id:activeReview.chunkId});b.id=created.id}else b.id=activeReview.id;await api('/api/review',b);$('#review-dialog').close();if($('#source-dialog').open)$('#source-dialog').close();current=await api('/api/student/'+encodeURIComponent(b.sid));if(!$('#student-dialog').open)$('#student-dialog').showModal();renderStudent();await loadStats();toast('核验结果已保存')}
function manualRecord(source,locator,withStudent=false,chunkId=null){activeReview={id:null,source:Number(source),locator,chunkId};const form=$('#review-form');form.reset();if(withStudent&&current)for(const k of ['sid','name','college'])form.elements[k].value=current.student[k]||'';$('#review-dialog').showModal()}
function compose(){const latest=new Map();for(const r of current.reviews)if(!latest.has(r.observation))latest.set(r.observation,r);const rows=[...latest.values()].filter(r=>r.decision==='已核实');if(!rows.length){toast('请先打开原件核对，并保存至少一条“已核实”记录');return}$('#compose-records').innerHTML=rows.map(r=>`<label class="review-check"><input type="checkbox" name="reviews" value="${r.id}" checked><span>${esc(r.year)} · ${esc(r.award)} ${esc(r.level)}<p>${esc(r.name)} · ${esc(r.sid)}</p></span></label>`).join('');const date=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(new Date());$('#compose-form').elements.date.value=date;$('#compose-dialog').showModal()}
async function exportProof(e){e.preventDefault();const f=new FormData(e.target),b=Object.fromEntries(f);b.reviews=f.getAll('reviews').map(Number);b.include_originals=f.has('include_originals');const btn=e.target.querySelector('[type=submit]');btn.disabled=true;try{await downloadProof(await api('/api/export',b),apiUrl);toast('材料已生成，草稿及依据已保存在你的线上档案库');$('#compose-dialog').close()}finally{btn.disabled=false}}
async function findDocuments(offset=0){docOffset=offset;const q=$('#doc-query').value.trim();if(!q)return;$('#document-results').innerHTML='<div class="loading">正在检索材料…</div>';const mode=$('#doc-mode').value;const r=await api((mode==='path'?'/api/files?':'/api/search?')+new URLSearchParams({q,offset}));$('#document-results').innerHTML=r.items.length?r.items.map(o=>`<article><h3><button class="text-button" data-source="${o.source||o.id}" data-locator="${esc(o.locator||'')}">${esc(o.path)}</button></h3><p>${esc(o.locator||'')} · ${esc(o.method||o.state||'')}</p>${o.excerpt?`<pre class="excerpt">${esc(o.excerpt)}</pre>`:''}</article>`).join(''):'<div class="empty">没有检索到内容。可切换文件名称检索，或在处理概览中查看待识别材料。</div>';pageButtons('#doc-pagination',offset,60,mode==='path'?r.total:r.items.length<60?offset+r.items.length:null,'documents')}
async function coverage(){await loadStats();$('#index-phase').textContent=[stats.meta.phase,stats.meta.ocr_phase].filter(Boolean).join(' · ');$('#coverage-states').innerHTML=Object.entries(stats.states).map(([s,n])=>`<button class="state-card" data-state="${esc(s)}">${esc(s)}<strong>${n.toLocaleString()}</strong></button>`).join('');const val=$('#file-state').value;$('#file-state').innerHTML='<option value="">全部状态</option>'+Object.keys(stats.states).map(s=>`<option>${esc(s)}</option>`).join('');$('#file-state').value=val;await listFiles(0)}
async function listFiles(offset=0){fileOffset=offset;const r=await api('/api/files?'+new URLSearchParams({state:$('#file-state').value,offset}));$('#file-results').innerHTML=r.items.map(o=>`<div class="file-row"><div class="file-path"><button class="text-button" data-source="${o.id}">${esc(o.path)}</button><p>${esc(o.ext)} · ${(o.size/1024).toLocaleString(undefined,{maximumFractionDigits:0})} KB${o.pages?' · '+o.pages+' 页':''}${o.message?' · '+esc(o.message):''}</p></div>${tag(o.state)}</div>`).join('')||'<div class="empty">当前状态下没有材料。</div>';pageButtons('#file-pagination',offset,60,r.total,'files')}
async function history(){const r=await api('/api/history');$('#history-results').innerHTML=r.items.length?`<table><thead><tr><th>材料编号</th><th>学号</th><th>生成时间</th><th></th></tr></thead><tbody>${r.items.map(o=>`<tr><td class="mono">${esc(o.id)}</td><td>${esc(o.sid)}</td><td>${esc(o.created.replace('T',' '))}</td><td><button class="text-button" data-history="${esc(o.id)}">下载材料</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">尚未生成证明材料。请在学生档案中核验记录后出具。</div>'}
async function switchView(v){view=v;$$('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===v));for(const key of Object.keys(labels))$('#view-'+key).hidden=key!==v;$('#page-title').textContent=$('#breadcrumb').textContent=labels[v][0];$('#page-description').textContent=labels[v][1];if(v==='coverage')await coverage();if(v==='history')await history()}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;const d=b.dataset;let p;if(d.history)p=api('/api/history/'+encodeURIComponent(d.history)+'/payload').then(payload=>downloadProof(payload,apiUrl));else if(d.view)p=switchView(d.view);else if(d.student)p=openStudent(d.student);else if(d.manual)manualRecord(d.manual,d.locator||'',d.withStudent==='1',d.chunk?Number(d.chunk):null);else if(d.source)p=openSource(d.source,d.locator||'');else if(d.review)reviewRecord(d.review);else if(d.state){$('#file-state').value=d.state;p=listFiles()}else if(d.page){const o=Number(d.offset);p=({students:findStudents,documents:findDocuments,files:listFiles}[d.page])(o)}else if(b.classList.contains('close-dialog'))b.closest('dialog').close();if(p)p.catch(fail)});
$('#search-form').addEventListener('submit',e=>{e.preventDefault();findStudents().catch(fail)});$('#document-form').addEventListener('submit',e=>{e.preventDefault();findDocuments().catch(fail)});$('#file-state').addEventListener('change',()=>listFiles().catch(fail));$('#review-form').addEventListener('submit',e=>saveReview(e).catch(fail));$('#compose-form').addEventListener('submit',e=>exportProof(e).catch(fail));$('#compose').addEventListener('click',compose);$('#refresh').addEventListener('click',async()=>{try{await loadStats();if(view==='students')await findStudents(studentOffset);if(view==='coverage')await coverage();toast('索引状态已刷新')}catch(e){fail(e)}});loadStats().then(()=>findStudents()).catch(fail);





function changePdfPage(step=0){const control=$('.pdf-controls');if(!control)return;const page=Math.min(Number(control.dataset.pdfTotal),Math.max(1,(Number($('#pdf-page').value)||1)+step));$('#pdf-page').value=page;showPdfPage(control.dataset.pdfId,page).catch(fail);$('#register-pdf-page').dataset.locator='第'+page+'页'}
document.addEventListener('click',e=>{const b=e.target.closest('[data-pdf-step]');if(b)changePdfPage(Number(b.dataset.pdfStep))});document.addEventListener('change',e=>{if(e.target.id==='pdf-page')changePdfPage()});

const evidenceShortcut=document.createElement('button');
evidenceShortcut.type='button';evidenceShortcut.className='text-button';
evidenceShortcut.textContent='按姓名 / 学号检索原文佐证 →';
evidenceShortcut.addEventListener('click',async()=>{
    const q=$('#query').value.trim();
    if(!q){toast('请先输入姓名或学号');return}
    $('#doc-query').value=q;$('#doc-mode').value='text';
    try{await switchView('documents');await findDocuments()}catch(e){fail(e)}
});
$('#result-note').replaceChildren(evidenceShortcut);

let pdfDocument=null,pdfSource=null,pdfRender=null,pdfSerial=0;
async function showPdfPage(id,number){
 const serial=++pdfSerial;const status=$('#pdf-status');if(!status)return;
 status.textContent='正在读取 PDF 原件…';
 if(pdfRender){try{pdfRender.cancel()}catch{}pdfRender=null}
 try{
  if(pdfSource!==String(id)||!pdfDocument){
   const pdfjs=await import(assetUrl('static/pdfjs/pdf.min.mjs'));
   pdfjs.GlobalWorkerOptions.workerSrc=assetUrl('static/pdfjs/pdf.worker.min.mjs');
   const doc=await pdfjs.getDocument({url:apiUrl('/api/source/'+id+'/file'),cMapUrl:assetUrl('static/pdfjs/cmaps/'),cMapPacked:true,standardFontDataUrl:assetUrl('static/pdfjs/standard_fonts/'),wasmUrl:assetUrl('static/pdfjs/wasm/')}).promise;
   if(serial!==pdfSerial){await doc.destroy();return}
   if(pdfDocument)await pdfDocument.destroy();pdfDocument=doc;pdfSource=String(id);
  }
  const page=await pdfDocument.getPage(number);if(serial!==pdfSerial)return;
  const canvas=$('#pdf-image');if(!canvas)return;
  const base=page.getViewport({scale:1}),viewport=page.getViewport({scale:Math.min(1.8,1500/base.width)});
  canvas.width=viewport.width;canvas.height=viewport.height;
  pdfRender=page.render({canvasContext:canvas.getContext('2d'),viewport});await pdfRender.promise;
  if(serial===pdfSerial)status.textContent='原件第 '+number+' 页';
 }catch(e){if(e.name!=='RenderingCancelledException'&&serial===pdfSerial)status.textContent='预览未完成，可点击“下载原件”查看。'+e.message}
}

setInterval(()=>{if(stats.meta.cloud_ready!=='1')loadStats().catch(()=>{})},30000);
